import argparse,json,sys
p=argparse.ArgumentParser();p.add_argument('--values',required=True);a=p.parse_args()
try:
 values=sorted(float(x) for x in a.values.split(','))
 if not values: raise ValueError('empty')
except ValueError:
 print('invalid values',file=sys.stderr);sys.exit(2)
print(json.dumps({'median':values[len(values)//2]}))

import argparse,json,sys
p=argparse.ArgumentParser();p.add_argument('--input',required=True);a=p.parse_args()
try:
 values=json.load(open(a.input,encoding='utf-8'))
 if not isinstance(values,list) or any(not isinstance(x,str) for x in values): raise ValueError('strings required')
except (ValueError,OSError):
 print('invalid input',file=sys.stderr);sys.exit(2)
result=sorted(set(values))
print(json.dumps({'values':result,'count':len(result)},ensure_ascii=False))
